def num_distinct(s, t):
    dp = [1] + [0] * len(t)            # dp[j]: ways to form t[:j]
    for ch in s:
        for j in range(len(t), 0, -1): # downward: use ch once per step
            if t[j - 1] == ch:
                dp[j] += dp[j - 1]
    return dp[-1]

