def num_distinct(s, t):
    m, n = len(s), len(t)
    dp = [[0] * (n + 1) for _ in range(m + 1)]   # dp[i][j]: ways s[:i] forms t[:j]
    for i in range(m + 1):
        dp[i][0] = 1                   # empty t: one way
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            dp[i][j] = dp[i - 1][j]    # skip s[i-1]
            if s[i - 1] == t[j - 1]:
                dp[i][j] += dp[i - 1][j - 1]   # or use it for t[j-1]
    return dp[m][n]

