def is_interleave(a, b, c):
    m, n = len(a), len(b)
    if m + n != len(c):
        return False
    dp = [False] * (n + 1)             # dp[j] for the current row i
    for i in range(m + 1):
        for j in range(n + 1):
            if i == 0 and j == 0:
                dp[j] = True
                continue
            k = i + j - 1              # next char of c to match
            from_a = i > 0 and dp[j] and a[i - 1] == c[k]
            from_b = j > 0 and dp[j - 1] and b[j - 1] == c[k]
            dp[j] = from_a or from_b
    return dp[n]

