from functools import lru_cache

def is_interleave(a, b, c):
    if len(a) + len(b) != len(c):
        return False

    @lru_cache(maxsize=None)
    def ok(i, j):                      # can a[i:] and b[j:] form c[i + j:]?
        if i == len(a) and j == len(b):
            return True
        k = i + j
        take_a = i < len(a) and a[i] == c[k] and ok(i + 1, j)
        return take_a or (j < len(b) and b[j] == c[k] and ok(i, j + 1))

    return ok(0, 0)

